const jobId = await polymer.prove.proof_request({
  chainId,
  contract: SRC_CONTRACT,
  eventSig: "OrderFilled(bytes32,uint256)",
  fromBlock, toBlock
});

Polymer then polls the result.

const { status, proof } = await polymer.prove.proof_query({ jobId });
if (status !== "DONE") await sleep(1000);
